UPDATE companies SET description='Blue Mountain Woodworks operates from Timbo, Arkansas, where it was founded in 1987 by Paul Gillam Sr. The business began as a one-man operation accommodating special orders, and over the past decade Paul Sr. has been joined full-time by his son, Paul Gillam, forming a father-son partnership.

The shop produces custom-made furniture, cabinets, and other wood products, working exclusively with native Arkansan hardwoods sourced from the Ozarks — including walnut, cherry, red oak, white oak, hickory, ash, maple, and aromatic red cedar. In addition to finished pieces, the company offers piecework services to meet the manufacturing needs of other businesses.

Customers range from individuals seeking long-lasting, American-made heirloom furniture to manufacturers requiring outsourced wood component production. The company serves the furniture and cabinetry markets directly and also supports broader manufacturing supply chains through its piecework capabilities.

The founders emphasize American-built quality and the use of local hardwoods as the foundation of their reputation, positioning each piece as a durable heirloom rather than a disposable product.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Cabinet manufacturing", "Wood piecework", "Hardwood milling and selection"], "industries": ["Furniture", "Cabinetry", "Manufacturing"], "materials": ["Walnut", "Cherry", "Red Oak", "White Oak", "Hickory", "Ash", "Maple", "Aromatic Red Cedar"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom furniture and cabinets built from native Ozark hardwoods", "Piecework services for manufacturing partners", "American-made heirloom quality"], "facts_used": ["Founded 1987 -> db", "Father-son partnership (Paul Sr. and Paul Gillam) -> /", "Headquarters Timbo, Arkansas -> /", "Custom furniture, cabinets, and wood products -> /", "Native Arkansan hardwoods: Walnut, Cherry, Red Oak, White Oak, Hickory, Ash, Maple, Aromatic Red Cedar -> /", "Piecework for manufacturing needs -> /", "American-made heirloom positioning -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We build our custom-made furniture, cabinets and other products using native Arkansan hardwoods from the Ozarks.", "founded_year": "1987", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='blue-mountain-woodworks' AND approved AND profile IS NULL;
UPDATE companies SET description='Blue Ridge Graphics operates from Charlottesville, Virginia, where it was founded in 1979 by John and Ruth Kulick as a family-owned venture born from a passion for T-shirt printing. The company''s first job was a print for Organic Gardening Magazine, and the business has remained in the family, with the founders'' sons Will and Jackson joining full-time in 2010 and 2011 to lead a second generation.

The shop specializes in screen printing using plastisol, water-based, algae-based, foil, metallic, glow-in-the-dark, simulated-process, and transfer inks, and added embroidery in 2021 to become a full-service decorator. It also supplies promotional products, corporate awards, trade-show booths, signage, and online company stores, serving customers across the Mid-Atlantic region from its Charlottesville facility.

Clients range from university athletic departments and student groups to retailers, local businesses, national event organizers, and international touring musicians. The company has also produced custom apparel for youth organizations such as 4-H and corporate uniform programs for area employers.

The founders'' original focus on craftsmanship evolved into a commitment to sustainable practices, earning the firm Sustainable Green Printing Partnership (SGP) certification in 2023—the only commercial apparel screen printer in the United States to hold it. Blue Ridge Graphics emphasizes low minimums of 24 pieces, a standard two-week turnaround after proof approval, and a stock of over 500 ink colors with PMS matching.', certifications=ARRAY['Sustainable Green Printing Partnership (SGP)']::text[], profile='{"capabilities": ["Screen printing (plastisol, water-based, algae ink, foil, metallic, glow-in-the-dark, simulated process, transfers)", "Embroidery", "Promotional products", "Corporate awards", "Trade show booths", "Signage", "Web stores", "Custom logo products", "Art and design assistance", "PMS color matching", "Rush order service"], "industries": ["University athletics", "Student groups", "Retailers", "Local businesses", "National events", "International musicians"], "materials": [], "equipment": [], "volume": "", "lead_time": "2 weeks after proof approval (standard)", "tolerances": "", "built_on": ["Only commercial apparel screen printer in the U.S. with Sustainable Green Printing Partnership certification", "Minimum order of 24 pieces with same decoration", "Standard two-week turnaround after proof approval", "Over 500 stock ink colors with PMS matching capability", "Family-owned since 1979, now second-generation run"], "facts_used": ["Founded in 1979 by John and Ruth Kulick -> /about", "Family-owned and operated -> /about", "Headquarters in Charlottesville, Virginia -> /about, db", "Screen printing services since 1979 -> /services", "Embroidery added in 2021 -> /about", "Promotional products, corporate awards, trade show booths, signage, web stores -> /about", "Sustainable Green Printing Partnership (SGP) certification in 2023 -> /about, /", "Minimum order 24 pieces -> /services, /", "Standard turnaround 2 weeks after proof approval -> /services, /", "Over 500 ink colors in stock, PMS color matching -> /services", "Clientele: university athletics, student groups, retailers, local businesses, national events, international musicians -> /about", "Second generation (Will and Jackson) joined in 2010-2011 -> /about", "Use of water-based and algae inks -> /about", "Only commercial apparel screen printer in US with SGP certification -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Our roots are in screen printing, and we have spent the last 40+ years honing and building on our craft.", "founded_year": "1979", "employee_count": "", "cage_code": "", "min_order": "24 pieces", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='blue-ridge-graphics-charlottesville-custom-t-shirts-embroidery' AND approved AND profile IS NULL;
UPDATE companies SET description='Blue Sky Smart Solutions is headquartered in Wichita, Kansas, and traces its roots to 1996 when it began as Blue Sky Satellite Services in Kansas City. The company remains family-owned and has expanded from a satellite installation business into a multi-state provider of smart home and connectivity solutions.

Today the firm employs over 300 technicians and support staff across offices in Kansas, Nebraska, Iowa, Missouri, and Wisconsin.

The customer base consists primarily of homeowners and families seeking connected-home technology, with the company positioning itself as a local expert that manages everything from equipment selection to ongoing support.

