age address", "Team background: former employees of GCH International, Harpring Inc., Griffin & Co. -> db description", "Services: sheet metal fabrication, structural components, architectural products, installation -> db description and homepage", "24/7 service availability -> db description", "Capabilities: CNC punching, welding, polishing, storage tanks, vessels, structural platforms, stairs, food-grade conveyors, HVAC ductwork, dust/fume removal, material handling -> db capabilities and services page", "Industries served: industrial, food processing, architectural, HVAC, material handling, pharmaceutical, restaurant/food service, institutional -> homepage and services page", "Materials: stainless steel, structural steel -> homepage and services page", "No founding year stated -> db", "No employee count stated -> db", "No certifications stated -> db", "No equipment model names stated -> db", "No volume, lead time, tolerances stated -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "BGMW offers solutions in many facets of sheet metal fabrication, structural components, institutional architectural products, as well as installation services", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bluegrass-metal-works-inc' AND approved AND profile IS NULL;
