UPDATE companies SET description='The company does not disclose its founding year or ownership structure, but its stated purpose is to provide quality contract packing and private label services with competitive pricing.

The firm functions as a national full-service contract and private label packer, handling both wet and dry products. Its capabilities span product development, recipe formulation, packaging, labeling, and regulatory compliance. The product portfolio includes spices, rubs, breading, hot sauces, barbecue sauces, salad dressings, syrups, juice drinks, marinades, jams, jellies, and pie fillings. Bluegrass Superior Foods manufactures acidified and shelf-stable foods under FDA compliance and holds organic certification through the US National Organic Program.

The company serves the food industry broadly, targeting startups, small brands, and established manufacturers. It emphasizes willingness to accept orders of any size, positioning itself as an alternative to co-packers with high minimum requirements. Bluegrass Superior Foods also produces for members of the Kentucky Proud program, a state marketing initiative for agricultural products.

The company''s stated differentiators include a commitment to a safe, injury-free workplace, environmental responsibility, and adherence to good manufacturing practices. It aims to minimize its environmental impact while ensuring products meet the highest safety and quality standards.', certifications=ARRAY['FDA compliance (acidified foods)','FDA compliance (shelf-stable foods)','Good Manufacturing Practices']::text[], profile='{"capabilities": ["Contract packing", "Private label packing", "Product development", "Recipe development", "Packaging (wet and dry)", "Labeling and nutritional compliance", "FDA compliance for acidified foods", "FDA compliance for shelf-stable foods", "Organic certification (US National Organic Program)", "Kentucky Proud program participation"], "industries": ["Food manufacturing", "Contract food packing", "Private label food", "Specialty food"], "materials": ["Spices", "Rubs", "Breading", "Hot sauces", "Barbecue sauces", "Salad dressings", "Syrups", "Juice drinks", "Marinades", "Jams", "Jellies", "Pie fillings"], "equipment": [], "volume": "Any quantity; no minimum order stated", "lead_time": "", "tolerances": "", "built_on": ["Accepts orders of any quantity with no minimum requirements", "USDA Organic certified under the National Organic Program", "FDA-compliant manufacturing of acidified and shelf-stable foods", "Member of Kentucky Proud, producing for other Kentucky Proud brands", "Offers full product development from concept to regulatory compliance"], "facts_used": ["Location: Louisville, Kentucky -> db", "National full-service contract and private label packer -> /services", "Product development, packaging, labeling & compliance services -> /services", "Product variety: spices, rubs, breading, hot sauces, BBQ sauces, salad dressings, syrup, juice drinks, marinades, jams, jellies, pie fillings -> /services", "FDA compliance for acidified and shelf-stable foods -> /services", "Certified Organic under US National Organic Program -> /services", "Member of Kentucky Proud -> /services", "Willing to offer services for any quantity, no minimums -> /services", "Mission: safe workplace, environmental responsibility, GMP adherence -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Bluegrass Superior Foods is a national full-service contract and private label packer serving a wide range of client-partners in the food industry.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "No minimum order", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bluegrass-superior-foods-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Bluejay Diagnostics was founded in 2015 in Acton, Massachusetts. The company is publicly traded on the NASDAQ under the ticker BJDX. It began as a diagnostics and medical device venture aimed at reducing wait times for critical medical results.

The company’s primary focus is the Symphony™ Suite, a near-patient testing system designed to deliver sample-to-result readings in approximately 20 minutes. Its first product candidate is an IL-6 test cartridge for sepsis triage, intended for use in hospital and long-term acute care settings. The self-contained cartridge can be disposed of in regular medical waste.

Bluejay serves the medical device and diagnostics industries, targeting clinicians in hospitals and long-term acute care facilities.

