 and Equipment \u2013 Bourgault", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bourgault-industries' AND approved AND profile IS NULL;
UPDATE companies SET description='The Alabama facility is one of several Brose locations across the Americas, though the exact founding year of this site is not publicly disclosed.

