UPDATE companies SET description='Carolina Farmstead operates from a workshop in Snow Hill, North Carolina, in the eastern part of the state. The company was founded by Wayne Noble, the family patriarch, after a car accident during his sons'' college years left Justin a paraplegic and Matt with a traumatic brain injury. Unable to pursue their original career paths, the brothers vowed to work together, combining Justin''s intellect and Matt''s physical strength to build a business that could accommodate their needs.

The shop produces custom, heirloom-quality furniture made entirely from solid wood. Each piece is handcrafted to the customer''s specified finish and dimensions, with options ranging from in-stock items ready to ship to fully customized designs developed through consultation. The team, led by craftsman Matt Noble, builds tables, chairs, and other furnishings one piece at a time, emphasizing traditional joinery and durable finishes.

Carolina Farmstead serves residential customers seeking long-lasting, made-to-order furniture for everyday use.

The business was created to provide meaningful employment for the Noble brothers after their accident, and that origin story remains central to its identity. The company highlights its Better Business Bureau accreditation, in-house white-glove delivery service that ships most orders within two weeks, and a commitment to solid-wood construction that avoids the shortcuts common in mass-market retail.', certifications=ARRAY['Better Business Bureau Accreditation']::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Handcrafted woodworking", "Custom finish application", "Design consultation", "White-glove delivery", "In-stock furniture fulfillment", "Customizable design modifications", "Fully custom furniture design"], "industries": ["Residential furniture", "Custom furniture manufacturing", "Home furnishings"], "materials": ["Solid wood"], "equipment": [], "volume": "", "lead_time": "Most orders ship within 2 weeks", "tolerances": "", "built_on": ["Handcrafted heirloom-quality furniture built one piece at a time", "Solid wood construction with custom finishes and measurements", "Better Business Bureau accredited", "In-house white-glove delivery with most orders shipping within two weeks", "Three purchasing tiers: in-stock, customizable designs, fully custom"], "facts_used": ["Founded by Wayne Noble for sons Justin and Matt after car accident -> db", "Located in Snow Hill, North Carolina -> db", "Handcrafts heirloom-quality furniture from solid wood -> /", "Offers in-stock, customizable, and fully custom purchasing options -> /", "Lead craftsman is Matt Noble -> /quality", "Better Business Bureau accredited -> /quality", "White-glove delivery service, most orders ship within 2 weeks -> db", "Featured on HGTV, PBS, Our State Magazine -> /", "Family-owned business -> / and db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "From our workshop in Eastern North Carolina, we handcraft heirloom-quality furniture one piece at a time", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='carolina-farmstead' AND approved AND profile IS NULL;
