ship_tags": []}'::jsonb, updated_at=now() WHERE slug='carpenter-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Catamount Solar was founded in 2011 in Randolph, Vermont, as a worker-owned cooperative. The company operates under an employee-ownership model in which all workers are either cooperative members or on a defined path to membership, giving each installer a direct stake in the business.

The cooperative specializes in the design and installation of solar photovoltaic systems for residential, commercial, and agricultural customers, as well as off-grid and battery-backup solutions.

Clients range from individual homeowners and family farms to businesses and institutions such as Crossett Brook Middle School in Duxbury.

